    if (budgetExhausted()) {
      pending.forEach(fi => noteFail(fkey(fi), 'per-card-heal-budget: card ' + k + ' hit ' + budget.max + ' heal calls — partial, requeue remaining'))
      break   // fail fast to partial; the card stops consuming the shared window budget
    }
