    const blocks = pending.map(i => '\n\n=== CARD ' + fkey(i) + ' (fragment ' + (i + 1) + '/' + grp.length + ') ===\n--- masked German (translatable only; {Tn}=masked span) ---\n' + grp[i].skeleton).join('')
